def homography(to,n=400):
 rows=[];values=[]
 for (x,y),(u,v) in zip([[0,0],[n,0],[n,n],[0,n]],to):
  rows.extend([[x,y,1,0,0,0,-u*x,-u*y],[0,0,0,x,y,1,-v*x,-v*y]]);values.extend([u,v])
 return np.r_[np.linalg.solve(rows,values),1].reshape(3,3)
def project(h,pts):
 pts=np.asarray(pts);p=np.c_[pts.reshape(-1,2),np.ones(pts.size//2)]@h.T
