def sample(a,points):
 x,y=points[...,0]-.5,points[...,1]-.5;w=a.shape[1];h=a.shape[0]
 x0=np.floor(x).astype(int);y0=np.floor(y).astype(int);dx=x-x0;dy=y-y0;result=np.zeros(x.shape)
 for j in [0,1]:
  for i in [0,1]:
   xi=x0+i;yi=y0+j;good=(xi>=0)&(xi<w)&(yi>=0)&(yi<h)
   z=np.full(x.shape,.5);z[good]=a[yi[good],xi[good]]
   result+=(dx if i else 1-dx)*(dy if j else 1-dy)*z
 return result.astype(np.float32)
def bottleneck(a,start,finish):
 # Maximum possible minimum pixel value on a four-neighbour path.
 n,m=a.shape;best=np.full(a.shape,-1.);best[start]=a[start];q=[(-float(a[start]),start)]
 while q:
  neg,(y,x)=heapq.heappop(q);value=-neg
  if value<best[y,x]:continue
  if (y,x)==finish:return value
  for yy,xx in [(y-1,x),(y+1,x),(y,x-1),(y,x+1)]:
   if 0<=yy<n and 0<=xx<m:
    new=min(value,float(a[yy,xx]))
    if new>best[yy,xx]:best[yy,xx]=new;heapq.heappush(q,(-new,(yy,xx)))
 raise RuntimeError('Unconnected patch')
