 x=int(round(cx));y=int(round(cy));a=p[y-r:y+r+1,x-r:x+r+1]
 corners=[(inset,inset),(inset,2*r-inset),(2*r-inset,inset),(2*r-inset,2*r-inset)]
 values=[float(a[q])for q in corners]
 if values[0]+values[3]>=values[1]+values[2]:high=[0,3];low=[1,2]
 else:high=[1,2];low=[0,3]
 highlevel=bottleneck(a,corners[high[0]],corners[high[1]])
 lowlevel=1-bottleneck(1-a,corners[low[0]],corners[low[1]])
 return {'cropCenter':[x,y],'radius':r,'portInset':inset,'sectorProbabilities':values,'sectorSeparation':min(values[i]for i in high)-max(values[i]for i in low),'highConnectionLevel':highlevel,'lowDisconnectionLevel':lowlevel,'connectionLevelsOrdered':highlevel<=lowlevel+1e-7,'levelMidpoint':.5*(highlevel+lowlevel)}
def summarize(js):
 ordered=[j for j in js if j['connectionLevelsOrdered'] and j['sectorSeparation']>0]
 s={'count':len(js),'orderedSeparatedCount':len(ordered),'minimumLevel':min(j['levelMidpoint']for j in js),'maximumLevel':max(j['levelMidpoint']for j in js),'medianLevel':float(np.median([j['levelMidpoint']for j in js])),'minimumSectorSeparation':min(j['sectorSeparation']for j in js)}
 if ordered:
