 results.append({'id':identity,'predictionSha256':sha(file),'savedMaskExactlyReproduced':True,'labelPhaseExchanged':bool(phase),'sourceWindow':w,'cropQuad':run['selectedCrop']['quad'],'targetProvenance':{'manifest':str((directory/'manifest.json').relative_to(root)),'manifestSha256':sha(directory/'manifest.json'),'annotationFile':audit['annotations'],'annotationSha256':audit['annotationsSha256'],'imageSha256':labelrow['imageSha256'],'materialLabels':str(labfile.relative_to(root)),'materialLabelsSha256':sha(labfile),'boundaryUncertaintyPixels':annotation['boundaryUncertaintyPixels'],'materialPixelCounts':labelrow['materialPixelCounts'],'scope':manifest['scope'],'transform':labelrow['transform']},'partialAnnotationThresholdDiagnostic':scores,'junctions':junctions,'summary':summary,'sensitivity':sensitivity,'maskedLossBlindSpotWitness':{'perturbation':'Complement only 5x5 field patches around approximate junction centers. No artifact enters inference or training. BCE computed in float64 from saved probabilities with numerical clipping; equality is exact because no known pixel changes. Body output remains unchanged.','changedPixels':int(patches.sum()),'changedKnownPixels':int((patches&known).sum()),'originalDirectExchangedBCE':before,'perturbedDirectExchangedBCE':after,'exactlyEqual':before==after}})
