/** Replay only preparation of saved predictions; no model or fitting. */
import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {prepare} from '../../../static/inverse/core/engine.js';
import {materialMask} from '../material-corrected-scenes-v1/material-fields.mjs';

const root='tmp/heart-learning/material-corrected-scenes-v1';
const out='tmp/heart-learning/material-topology-audit-v1';
const read=async p=>JSON.parse(await fs.readFile(p,'utf8'));
const hash=x=>createHash('sha256').update(x).digest('hex');
const probe=await read(root+'/probe/manifest.json');
const pipeline=await read(root+'/pipeline/report.json');
const identities=['real-cf2d0fcff65d7386-body-1','real-d5b0aa8d4d2465ee-body-1'];
const cases=[];
for(const id of identities){
  const source=probe.rows.find(x=>x.id===id);
  const row=pipeline.rows.find(x=>x.id===id&&x.method==='candidate-joint');
  const asset=source.assets.candidate.material;
  const bytes=await fs.readFile(root+'/probe/'+asset.path);
  assert.equal(hash(bytes),asset.sha256);
  const field=Float32Array.from({length:probe.resolution**2},(_,i)=>bytes.readFloatLE(4*i));
  const predicted=materialMask(field,probe.resolution,source.window,row.selectedCrop.quad,row.resolution);
  assert.equal(hash(predicted.mask),row.targetMaskSha256);
  const target=prepare({type:'mask',resolution:row.resolution,mask:predicted.mask.slice()},
    {...pipeline.configuration,invert:false,removeSpecks:0,fillHoles:0}).target;
  assert.deepEqual(target.sourceImage.mask,predicted.mask);
  assert.deepEqual(target.sourceImage.probability,Float32Array.from(predicted.mask));
  let fractional=0,uncertain=0,absoluteDifference=0;
  for(let i=0;i<predicted.mask.length;i++){
    const p=predicted.probability[i];
    fractional+=Number(p>0&&p<1);
    uncertain+=Number(p>.01&&p<.99);
    absoluteDifference+=Math.abs(p-predicted.mask[i]);
  }
  cases.push({id,resolution:row.resolution,predictionSha256:hash(bytes),maskSha256:hash(predicted.mask),
    maskExactlyReproduced:true,fitterReceivesBinaryProbability:true,pixels:predicted.mask.length,
    fractionalPredictionPixels:fractional,betweenOneAndNinetyNinePercentPixels:uncertain,
    meanAbsoluteSoftToBinaryDifference:absoluteDifference/predicted.mask.length});
}
const sources=['tmp/heart-learning/material-corrected-scenes-v1/replay.mjs',
  'tmp/heart-learning/material-corrected-scenes-v1/material-fields.mjs',
  'scripts/inverse/hard-photo-target.mjs','scripts/inverse/learning/replay-material-resolution.mjs',
