  'static/inverse/core/direct/fit.js','static/inverse/core/direct/image-objective.js'];
const sourceHashes={};for(const p of sources)sourceHashes[p]=hash(await fs.readFile(p));
const report={schema:'material-probability-handoff-audit-1',status:'complete-preparation-only',
  scriptSha256:hash(await fs.readFile(new URL(import.meta.url))),sourceHashes,cases,
  findings:[
    'The corrected real-photo experiment thresholds the predicted field and prepares a binary mask. Saved probability PNGs do not enter its fitter.',
    'This matches the current paint workflow: importing stores mask cells, and Find snit prepares that binary drawing. Native sourceRaster preserves original binary cells, not photographic mixture values.',
    'The direct fitter can consume sourceImage.probability for its multi-scale objective. A future soft-field ablation can keep sourceImage.mask, crop, coverage and all final binary-mask/geometry/paper checks fixed.',
    'This is an explicit mask-track design, not proof of a runtime defect. Passing learned soft values is untested, and cross-entropy probabilities are not automatically calibrated photographic coverage.'
  ],scope:'Two previously inspected development predictions. No model inference, fitter run, threshold tuning, runtime edit, new success claim or browser change.'};
await fs.writeFile(out+'/handoff.json',JSON.stringify(report,null,2)+'\n');
